val name: String = "Alice"   // immutable (like final)
var count = 0                 // mutable, type inferred
count++

// Null safety — must declare nullable with ?
val nullableName: String? = null

// Safe call operator ?.
val length = nullableName?.length      // null (not NPE)

// Elvis operator ?:
val len = nullableName?.length ?: 0   // 0 if null

// Not-null assertion !! (throws NPE if null — use sparingly)
val forced = nullableName!!.length

// Smart cast — compiler knows type after null check
if (nullableName != null) {
    println(nullableName.length)  // no ?. needed here!
}

// Null-safe let
nullableName?.let { name ->
    println("Name is: $name")
}
```

