// when as expression (returns value)
val grade = when (score) {
    in 90..100 -> "A"
    in 80..89  -> "B"
    in 70..79  -> "C"
    else       -> "F"
}

// when without argument (replaces if/else chain)
when {
    x < 0    -> println("negative")
    x == 0   -> println("zero")
    else     -> println("positive")
}

// when with type checking
when (val obj = getObject()) {
    is String  -> println("String: ${obj.length}")  // smart cast!
    is Int     -> println("Int: ${obj * 2}"
    is List<*> -> println("List: ${obj.size}")
    else       -> println("other")
}

// when with multiple values per branch
when (day) {
    "Monday", "Tuesday" -> println("Early week")
    "Wednesday"          -> println("Mid week")
    "Thursday", "Friday" -> println("Late week")
    else                 -> println("Weekend")
}
