// Sealed class — restricted hierarchy (all subclasses in same file)
sealed class Result<out T> {
    data class Success<T>(val value: T) : Result<T>()
    data class Failure(val error: Throwable) : Result<Nothing>()
    object Loading : Result<Nothing>()
}

// Exhaustive when (compiler verifies all cases covered)
fun handleResult(r: Result<Int>) = when (r) {
    is Result.Success -> println("Got ${r.value}")
    is Result.Failure -> println("Error: ${r.error.message}")
    Result.Loading    -> println("Loading...")
    // No 'else' needed — sealed class is exhaustive!
}

// Result usage
fun divide(a: Int, b: Int): Result<Int> {
    return if (b == 0) Result.Failure(ArithmeticException("div by 0"))
           else Result.Success(a / b)
}

when (val result = divide(10, 2)) {
    is Result.Success -> println(result.value)   // 5
    is Result.Failure -> println(result.error.message)
    Result.Loading    -> println("loading")
}
```

```kotlin
val person = Person("Alice", 30)

// let — transform, returns lambda result, 'it' = receiver
val len = person.let { p -> p.name.length }  // 5

// apply — configure object, returns receiver, 'this' = receiver
val configured = StringBuilder().apply {
    append("Hello")
    append(", World")
}  // StringBuilder with content

// also — side effect, returns receiver, 'it' = receiver
val p2 = person.also { p -> println(p.name) }  // logs, returns person

// run — execute block, returns lambda result, 'this' = receiver
val greeting = person.run {
    "${name} is ${age}"   // 'this' = person
}

// with — not an extension, returns lambda result
with(person) {
    println(name)   // 'this' = person
    println(age)
}
```

| Function | Receiver | Returns | Use case |
|----------|----------|---------|----------|
| `let` | `it` | Lambda result | Transform nullable |
| `apply` | `this` | Receiver | Configure object |
| `also` | `it` | Receiver | Side effects |
| `run` | `this` | Lambda result | Execute block |
| `with` | `this` | Lambda result | Group calls |

