import kotlinx.coroutines.*

// Launch coroutine
fun main() = runBlocking {
    launch {
        delay(100)            // suspend (non-blocking!)
        println("World!")
    }
    println("Hello,")
}

// async/await — for values
suspend fun fetchData(): String {
    delay(1000)
    return "data"
}

val result = coroutineScope {
    val a = async { fetchData() }   // starts immediately
    val b = async { fetchData() }   // starts immediately (parallel!)
    "${a.await()} + ${b.await()}"  // wait for both
}

// Cancellation
val job = launch {
    repeat(10) {
        println("Working $it")
        delay(500)
    }
}
delay(1200)
job.cancel()   // cooperative cancellation
```

`delay()` suspends the coroutine without blocking the thread — thousands of coroutines can share one thread.

```kotlin
import kotlinx.coroutines.flow.*

// Flow — cold async stream
fun numbersFlow(): Flow<Int> = flow {
    for (i in 1..5) {
        delay(100)    // non-blocking
        emit(i)       // send value downstream
    }
}

fun main() = runBlocking {
    numbersFlow()
        .map { it * it }             // transform
        .filter { it > 5 }           // filter
        .collect { println(it) }     // collect (terminal)
}
// prints: 9, 16, 25

// StateFlow — hot stream with current state
val stateFlow = MutableStateFlow(0)
stateFlow.value = 1
stateFlow.collect { println(it) }   // always gets latest value

// SharedFlow — hot stream for events
val sharedFlow = MutableSharedFlow<Int>()
sharedFlow.emit(42)
sharedFlow.collect { println(it) }

// Useful operators
numbersFlow()
    .onEach { println("before: $it") }
    .map { it * 2 }
    .take(3)
    .toList()  // terminal: collect to list
```

