max(3, 5)       // 5
max("abc", "xyz")  // "xyz"

// Generic class
class Box<T>(val value: T) {
    fun map(f: (T) -> T) = Box(f(value))
    override fun toString() = "Box($value)"
}

// Variance
interface Producer<out T> { fun produce(): T }  // out = covariant (read-only)
interface Consumer<in T> { fun consume(item: T) }  // in = contravariant (write-only)

// Reified — preserves type at runtime (inline only)
inline fun <reified T> isType(obj: Any) = obj is T
isType<String>("hello")  // true
isType<Int>("hello")     // false

// Without reified, T is erased at runtime:
// obj is T  would fail with "Cannot check for erased type"

// Practical use: parse JSON to typed object
inline fun <reified T> parseJson(json: String): T {
    return objectMapper.readValue(json, T::class.java)
}
